function Get-Cp423BraceBlock {
    param([string]$Text,[string]$AnchorPattern,[string]$Description)
    $anchors = [regex]::Matches($Text,$AnchorPattern)
    if ($anchors.Count -ne 1) { throw "CP423 $Description expected one anchor, found $($anchors.Count)" }
    $open = $Text.IndexOf('{',$anchors[0].Index); if ($open -lt 0) { throw "CP423 $Description opening brace missing" }
    $depth=0
    for ($index=$open; $index -lt $Text.Length; $index += 1) {
        if ($Text[$index] -eq '{') {$depth += 1}
        elseif ($Text[$index] -eq '}') {$depth -= 1; if ($depth -eq 0) {return $Text.Substring($open + 1,$index - $open - 1)}}
    }
    throw "CP423 $Description closing brace missing"
}

